def seconds_to_start(respects):
    for i in range(len(respects)):
        if i == 0:  # starting parrot
            return respects[i]
        else:
            # rep 2, to get parrots taking some time to start
            keep_count = 0

            # odd parity check
            if i % 2 != 0:
                keep_count += 1

            # Performance Guarantee i >= (res+lo=2)/2
            gap = 0  # only positive values express
            j = i-1
            k = i+1

            # j and k exits the circle
            while (j >= 0 or k < len(respects)) and (j != i or k != i):
                gap += min(k - j - 1, i)

                if gap < 2:
                    break

                while k < len(respects):
                    if k < min(i-1, j):
                        k += 1
                    else:
                        j = k - 1
                        k += 1

            keep_count += gap // 2
            # if k does not contain i, we will need odd amount of rep for i
            if k != i:
                keep_count += 1

            yield keep_count

counted = {i: [] for i in range(max(respects) + 1)}

for second_count in seconds_to_start(respects):
    for i in range(max(respects)):
        counted[i].append(second_count)

for res in counted.values():
