    adj_list[v-1].append(u-1)

# Function to check if a pair of nodes form a matching
def is_matching_pair(u, v, low, cover):
    if low[u] == len(adj_list[u]) and v in cover:
        return True
    if low[v] == len(adj_list[v]) and u in cover:
        return True
    if low[u] >= low[v] and v in cover:
        return False
    for neighbor in adj_list[v]:
        if neighbor in cover:
            continue
        if not is_matching_pair(v, neighbor, low, cover + [v]):
            return False
    return True

# Recursive function to count the number of ways to form a perfect matching
def count_ways(u, v, low):
    if u == v:
        return 0
    covers = [u]
    low[u] = len(covers)
    for neighbor in adj_list[u]:
        if is_matching_pair(u, neighbor, low, covers):
            total_ways = 0
            for cover in covers:
                total_ways += 2 ** (low[cover] + 1)
            yield total_ways
    for cover in covers:
        del covers[low[cover]]
        yield count_ways(u, v, low)

# Count the number of perfect matchings
result = 0
for cover in count_ways(0, len(adj_list[0])):
    result += cover

