def rearrange_matrix(matrix):
    rows, cols = len(matrix), len(matrix[0])
    count_zeros = 0

    for row in matrix:
        count_zeros += row.count('0')

    if count_zeros % cols == 0 and any(row.count('0') == 0 for row in matrix):
        # Generate all possible column permutations
        from itertools import permutations
        for perm in permutations(range(cols)):
            b = [[0] * rows for _ in range(cols)]

            for col_pos, col in enumerate(perm):
                for row, row_data in enumerate(matrix):
                    matrix[row][col] = '1' if b[row][col] == 0 else '0'
                    b[row][col] = row + 1 + 2 ** (col - 1)

            if is_good(b):
                return '\n'.join([' '.join(map(str, row)) for row in b])
        return 'NO'
    else:
        return 'NO'

