        return factor

def f(n, k, a, memo):
    if k == 1:
        return 1
    if n == 0:
        return 0
    if (k, n) in memo:
        return memo[(k, n)]
    res = 1
    for i in range(k):
        res += f(n-1, k-i-1, a, memo)*moebius(k-i-1)
    res %= mod
    memo[(k, n)] = res
    return res

