def bfs(circles):
    visited = set()
    for x, y in circles:
        if (x, y) not in visited:
            if bfs_util((x, y), set(), circles, visited):
                return True
    return False

def bfs_util(node, visited, circles, visited_nodes):
    queue = [node]
    visited.add(node)
    while queue:
        (x, y), t = queue.pop(0)
        if t == 0:
            return True
        for next_position in [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]:
            if 0 <= next_position[0] < 100 and 0 <= next_position[1] < 100 and (next_position, t) not in visited_nodes:
                if bfs_util(next_position, visited, circles, (next_position, t) in visited_nodes):
                    return True
    visited.remove(node)
    return False

