from collections import deque

def is_simple_segment(a, b, l, r):
    stack = deque()
    path = []

    for i in range(l-1, -1, -1):
        x = 1
        while stack and b[i] != '*':
            if b[i] == '/':
                x = x / stack[-1]
            else:
                x = x * stack[-1]
            stack.pop()
        stack.append(a[i])

        while stack and stack[-1] == 0:
            stack.pop()

        if not stack:
            path.append(True)
        else:
            path.append(False)

    count = 0
    for i in range(l-1, r):
        if path[i]:
            count += 1

    return count

