def count_simple_segments(n, a, b):
    from math import gcd
    lcm = a[0]
    for ai in a:
        lcm *= ai
    divisors = [1]

    for ai in a:
        m = 1
        for bi in b:
            if bi == '/':
                m *= ai
            elif bi == '*':
                m = (m * ai) // gcd(m, ai)
        divisors.append(m * lcm // gcd(m, lcm))

    return n * (reduce(lambda a, b: a * b, divisors, 1) // (lcm * lcm))

