from collections import defaultdict

def rearrange_to_good_matrix(matrix):
    n = len(matrix)
    ones_per_column = defaultdict(int)
    cols_to_swap = []

    for col in range(n):
        ones = sum(matrix[row][col] for row in range(n))
        for row in range(n):
            if matrix[row][col] == "1":
                ones_per_column[row] += 1

    seen_rows_with_ones = set()
    for row in range(n):
        if ones_per_column[row] == 1 and row not in seen_rows_with_ones:
            seen_rows_with_ones.add(row)
        if ones_per_column[row] > 1:
            cols_to_swap.append(row)

    if len(seen_rows_with_ones) == n:
        return "YES"
    else:
        return "NO"

